ee:message.ee:set-payload:
%dw 2.0
output application/xml
---
{
    BAPI_SALESORDER_GETSTATUS: {
        "import": {
            SALESDOCUMENT: (vars.salesDoc as Number) as String { format: "0000000000" }
        }
    }
}

%dw 2.0
output application/json skipNullOn = "everywhere"
var r = payload.BAPI_SALESORDER_GETSTATUS
---
{
    salesDocument: vars.salesDoc,
    mechanism: "BAPI (synchronous) — BAPI_SALESORDER_GETSTATUS",
    statusInfo: (r.tables.STATUSINFO.*row default []),
    messages:   (r.tables.RETURN.*row default []) map {
        messageType: $.TYPE default "",
        message:     $.MESSAGE default ""
    }
}

ee:variables.ee:set-variable:
%dw 2.0
output application/java
var o = payload default {}
// Defaults come from config.yaml (orderDefaults.*) so another SAP system only
// needs settings changes. Any field in the request body overrides them.
fun d(key) = p("orderDefaults." ++ key)
var reqDelivery = o.reqDeliveryDate default d("reqDeliveryDate")
var raw = (o.items default [])
var items = if (isEmpty(raw)) [{}] else raw
---
{
    docType: (o.docType default d("docType")),
    salesOrg: (o.salesOrg default d("salesOrg")),
    distrChannel: (o.distrChannel default d("distrChannel")),
    division: (o.division default d("division")),
    poNumber: (o.poNumber default d("poNumber")),
    docDate: (o.docDate default d("docDate")),
    priceDate: (o.priceDate default d("priceDate")),
    reqDeliveryDate: reqDelivery,
    soldTo: (o.soldTo default d("soldTo")) as String,
    items: (items map (it, i) -> {
        itemNo: (it.itemNo default (((i + 1) * 10) as String { format: "000000" })),
        material: (it.material default d("material")),
        plant: (it.plant default d("plant")),
        quantity: (it.quantity default d("quantity")) as String,
        unit: (it.unit default d("unit")),
        reqDate: (it.reqDate default reqDelivery),
        // Customer's own material identifier (SAP CUST_MAT35 -> "Customer
        // Material Numb" column, KDMAT). This is a pure passthrough field, so
        // it displays the caller's product code even when the ordered material
        // is the demo-safe B-7000. Capped at 35 chars. Blank -> left empty.
        customerMaterial: ((it.customerMaterial default "") as String)[0 to 34] default ""
    })
}

ee:message.ee:set-payload:
%dw 2.0
output application/xml
var ord = vars.order
---
{
    BAPI_SALESORDER_CREATEFROMDAT2: {
        "import": {
            ORDER_HEADER_IN: {
                DOC_TYPE: ord.docType, SALES_ORG: ord.salesOrg,
                DISTR_CHAN: ord.distrChannel, DIVISION: ord.division,
                PURCH_NO_C: ord.poNumber, DOC_DATE: ord.docDate,
                PRICE_DATE: ord.priceDate, REQ_DATE_H: ord.reqDeliveryDate
            },
            TESTRUN: "X"
        },
        tables: {
            ORDER_PARTNERS: { row: { PARTN_ROLE: "AG", PARTN_NUMB: ord.soldTo } },
            ORDER_ITEMS_IN: { (ord.items map (it) -> { row: {
                ITM_NUMBER: it.itemNo, MATERIAL: it.material, PLANT: it.plant,
                TARGET_QTY: it.quantity, TARGET_QU: it.unit,
                (CUST_MAT35: it.customerMaterial) if ((it.customerMaterial default "") != "") } }) },
            // CREATEFROMDAT2 ignores optional item fields (e.g. CUST_MAT35) unless
            // they're flagged 'X' here with UPDATEFLAG 'I'. Structural fields are
            // flagged too so behaviour is unchanged for the fields already working.
            ORDER_ITEMS_INX: { (ord.items map (it) -> { row: {
                ITM_NUMBER: it.itemNo, UPDATEFLAG: "I",
                MATERIAL: "X", PLANT: "X", TARGET_QTY: "X", TARGET_QU: "X",
                (CUST_MAT35: "X") if ((it.customerMaterial default "") != "") } }) },
            ORDER_SCHEDULES_IN: { (ord.items map (it) -> { row: {
                ITM_NUMBER: it.itemNo, REQ_DATE: it.reqDate, REQ_QTY: it.quantity } }) }
        }
    }
}

ee:variables.ee:set-variable:
%dw 2.0
output application/java
var msgs = (payload.BAPI_SALESORDER_CREATEFROMDAT2.tables.RETURN.*row default []) map {
    messageType: ($.TYPE default "") as String,
    id:          ($.ID default "") as String,
    number:      ($.NUMBER default "") as String,
    message:     ($.MESSAGE default "") as String
}
---
{
    hasError: !isEmpty(msgs filter ((m) -> m.messageType == "E" or m.messageType == "A")),
    messages: msgs
}

